(()=>{
const grid=document.querySelector('#video-grid');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
let timer,active,player,api,sound=false;
const soundButton=document.querySelector("#preview-sound");soundButton.onclick=()=>{sound=!sound;soundButton.setAttribute("aria-pressed",String(sound));soundButton.textContent=sound?"Mute previews ♫":"Enable preview sound ♫";if(player?.unMute){if(sound)player.unMute();else player.mute();}};
function stop(){clearTimeout(timer);active=null;if(player){player.destroy();player=null;}document.querySelectorAll('.hover-preview').forEach(n=>n.remove());}
function loadAPI(){return api ||= new Promise(resolve=>{if(window.YT?.Player)return resolve();const previous=window.onYouTubeIframeAPIReady;window.onYouTubeIframeAPIReady=()=>{previous?.();resolve();};const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';document.head.append(script);});}
grid.addEventListener('pointerover',e=>{const card=e.target.closest('.video-card');if(!card||card.contains(e.relatedTarget)||e.pointerType==='touch'||reduced.matches)return;stop();active=card;timer=setTimeout(async()=>{await loadAPI();if(active!==card||!card.isConnected||document.hidden)return;const id=new URL(card.href).searchParams.get('v');const mount=document.createElement('div');mount.className='hover-preview';const host=document.createElement('div');mount.append(host);card.querySelector('.video-thumb').append(mount);player=new YT.Player(host,{videoId:id,playerVars:{playsinline:1,controls:0,rel:0,origin:location.origin},events:{onReady:e=>{if(active===card){if(sound)e.target.unMute();else e.target.mute();e.target.playVideo();}else stop();},onAutoplayBlocked:e=>{e.target.mute();e.target.playVideo();sound=false;soundButton.textContent="Enable preview sound ♫";soundButton.setAttribute("aria-pressed","false");},onError:()=>stop()}});},1500);});
grid.addEventListener('pointerout',e=>{const card=e.target.closest('.video-card');if(card&&!card.contains(e.relatedTarget))stop();});
new MutationObserver(()=>{if(active&&!active.isConnected)stop();}).observe(grid,{childList:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});window.addEventListener('pagehide',stop);window.addEventListener('scroll',()=>{if(active){const r=active.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)stop();}},{passive:true});reduced.addEventListener('change',stop);
if(!reduced.matches&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}}),{threshold:.08});document.querySelectorAll('.reel-card,.service-row,.steps article').forEach(el=>{el.classList.add('reveal');observer.observe(el);});}
})();
